static int dfs(int x, int d) {
    if (x == 3) return d;
    seen[x] = true;
    for (int y : g[x]) {
        if (seen[y]) continue;
        int r = dfs(y, d + 1);
        if (r != -1) return r;
    }
    return -1;
}

function dfs(x, d) {
  if (x === 3) return d;
  seen[x] = true;
  for (const y of g[x]) {
    if (seen[y]) continue;
    const r = dfs(y, d + 1);
    if (r !== -1) return r;
  }
  return -1;
}

