const g = [[1], [0, 2], [1], [4], [3]];
const seen = new Set([0]);
const st = [0];
while (st.length) {
  for (const y of g[st.pop()]) {
    if (seen.has(y)) continue;
    seen.add(y);
    st.push(y);
  }
}
console.log(seen.size);

vector<int> g[] = {{1}, {0, 2}, {1}, {4}, {3}};
vector<bool> seen(5);
stack<int> st;
st.push(0); seen[0] = true;
while (!st.empty()) {
    int x = st.top(); st.pop();
    for (int y : g[x]) {
        if (seen[y]) continue;
        seen[y] = true; st.push(y);
    }
}
cout << count(seen.begin(), seen.end(), true);
